# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import pytest
import torch

import flag_gems

from . import accuracy_utils as utils


# Test covers all FLOAT_DTYPES to validate the kernel's correctness for every
# supported input type (the kernel upcasts to float32 internally, then casts
# back). torch.special.bessel_y0 only supports float32/float64 on all backends,
# so we compute the reference in float32 for Half/BFloat16 inputs and cast back.
# y0 is only defined for x > 0, so the input is sampled from the positive domain
# here and the boundary behaviour is covered by the test below.
@pytest.mark.special_bessel_y0
@pytest.mark.parametrize("shape", utils.POINTWISE_SHAPES)
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_special_bessel_y0(shape, dtype, caplog):
    inp = torch.empty(shape, dtype=dtype, device=flag_gems.device).uniform_(0.1, 20.0)
    ref_inp = utils.to_reference(inp, True)
    if dtype in (torch.float16, torch.bfloat16):
        ref_out = torch.special.bessel_y0(ref_inp.float()).to(dtype)
    else:
        ref_out = torch.special.bessel_y0(ref_inp)
    with caplog.at_level("DEBUG", logger="flag_gems.ops.special_bessel_y0"):
        with flag_gems.use_gems():
            res_out = torch.special.bessel_y0(inp)

    assert "GEMS SPECIAL_BESSEL_Y0" in caplog.text
    utils.gems_assert_close(res_out, ref_out, dtype)


@pytest.mark.special_bessel_y0
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_special_bessel_y0_out_of_domain(dtype, caplog):
    # y0 is undefined for x <= 0: the reference returns -inf at zero and nan for
    # negative inputs and for both infinities. These are exact values, so they
    # are compared with equality semantics rather than a tolerance.
    inp = torch.tensor(
        [0.0, -0.0, -1.0, -20.0, float("inf"), float("-inf"), float("nan")],
        dtype=dtype,
        device=flag_gems.device,
    )
    ref_inp = utils.to_reference(inp, True)
    ref_out = torch.special.bessel_y0(ref_inp.float()).to(dtype)

    with caplog.at_level("DEBUG", logger="flag_gems.ops.special_bessel_y0"):
        with flag_gems.use_gems():
            res_out = torch.special.bessel_y0(inp)

    assert "GEMS SPECIAL_BESSEL_Y0" in caplog.text
    torch.testing.assert_close(
        res_out.to(torch.float32).cpu(),
        ref_out.to(torch.float32).cpu(),
        equal_nan=True,
        rtol=0,
        atol=0,
    )


@pytest.mark.special_bessel_y0
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_special_bessel_y0_non_contiguous(dtype, caplog):
    # A transposed view exercises the strided path of the pointwise kernel.
    inp = torch.empty((16, 32), dtype=dtype, device=flag_gems.device).uniform_(
        0.1, 20.0
    )
    inp = inp.t()
    ref_inp = utils.to_reference(inp, True)
    if dtype in (torch.float16, torch.bfloat16):
        ref_out = torch.special.bessel_y0(ref_inp.float()).to(dtype)
    else:
        ref_out = torch.special.bessel_y0(ref_inp)

    with caplog.at_level("DEBUG", logger="flag_gems.ops.special_bessel_y0"):
        with flag_gems.use_gems():
            res_out = torch.special.bessel_y0(inp)

    assert "GEMS SPECIAL_BESSEL_Y0" in caplog.text
    assert res_out.shape == ref_out.shape
    utils.gems_assert_close(res_out, ref_out, dtype)
